CREATE TRIGGER MKM_TBI_Sales_Item
  BEFORE INSERT ON MKM_Sales_Item
  FOR EACH ROW
BEGIN
  DECLARE dDate   DATETIME   := NOW();
  DECLARE nCatId  DECIMAL(38,10) := 0;
  DECLARE nUserId DECIMAL(38,10);
  SELECT Mdate, User_Id
    INTO dDate, nUserId
    FROM MKM_Sale
   WHERE Id = NEW.Sales_Id;
  BEGIN
    SELECT Prod_Id
      INTO NEW.Prod_Id
      FROM MKM_Prod_Serial
     WHERE Serial = NEW.Serial;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unregistered Serial Number';
  END;
  SELECT Cat_Id
    INTO nCatId
    FROM MKM_Product
   WHERE Id = NEW.Prod_Id;
  SELECT SPoints, Wdays
    INTO NEW.Points, NEW.Wdays
    FROM MKM_Cat
   WHERE Id = nCatId;
  SET NEW.Edate = dDate + NEW.Wdays;
  UPDATE MKM_Member 
     SET Points = IFNULL(Points, 0) + NEW.Points
   WHERE User_Id = nUserId;
END$$
DELIMITER ;

