CREATE TRIGGER
  MKM_TBI_Inst_Item
  Before Insert
  On MKM_Inst_Items
  For Each Row
BEGIN
  DECLARE nSaleId  DECIMAL(38,10);
  DECLARE nCatId   DECIMAL(38,10) := 0;
  DECLARE nUserId  DECIMAL(38,10);
  Begin
    Select Sales_Id
      Into nSaleId
      From MKM_Sales_Item
      Where Serial=NEW.Serial;
  Exception
    When No_Data_Found Then
      nSaleId := null;
    When Others Then
      nSaleId := null;
  End;
  If nSaleId IS Not NULL Then
    Select User_Id
      Into nUserId
      From MKM_MInstallment
      WHere Id=NEW.Inst_Id;
    Select Prod_Id
      Into NEW.Prod_Id
      From MKM_Prod_Serial
     Where Serial=NEW.Serial;
    Select Cat_Id
      Into nCatId
      FROM MKM_Product
     Where Id=NEW.Prod_Id;
    Select IPoints
      Into NEW.Points
      FROM MKM_Cat
     Where Id=nCatId;
    UPDATE MKM_Member SET Points=IFNULL(Points,0)+NEW.Points
     WHERE User_Id=nUserId;
  Else
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unsold Serial Number';
  End If;
Exception
  When Others Then
    NULL;
END$$
DELIMITER ;

